// Split & Normalize PhantomBuster output
const raw = $input.first().json;
let leads = [];

// PhantomBuster returns output as JSON string or object
try {
  if (typeof raw.output === 'string') {
    leads = JSON.parse(raw.output);
  } else if (Array.isArray(raw.output)) {
    leads = raw.output;
  } else if (raw.resultObject) {
    leads = typeof raw.resultObject === 'string'
      ? JSON.parse(raw.resultObject)
      : raw.resultObject;
  } else if (Array.isArray(raw)) {
    leads = raw;
  }
} catch (e) {
  // If parse fails, try the whole input
  if (Array.isArray($input.all().map(i => i.json))) {
    leads = $input.all().map(i => i.json);
  }
}

if (!Array.isArray(leads)) leads = [leads];

// Normalize each lead
const normalized = leads.map(lead => ({
  fullName: (lead.fullName || lead.name || lead.firstName && lead.lastName
    ? (lead.firstName + ' ' + lead.lastName).trim() : '').trim(),
  firstName: (lead.firstName || (lead.fullName || '').split(' ')[0] || '').trim(),
  lastName: (lead.lastName || (lead.fullName || '').split(' ').slice(1).join(' ') || '').trim(),
  company: (lead.companyName || lead.company || lead.organizationName || '').trim(),
  role: (lead.title || lead.jobTitle || lead.headline || lead.role || '').trim(),
  linkedinProfileUrl: (lead.linkedinProfileUrl || lead.profileUrl || lead.linkedInUrl || lead.url || '').trim(),
  profileUrl: (lead.profileUrl || lead.linkedinProfileUrl || '').trim(),
  website: (lead.companyUrl || lead.website || lead.companyWebsite || '').trim(),
  location: (lead.location || lead.city || lead.country || '').trim(),
  country: (lead.country || lead.location || '').trim(),
  connectionDegree: lead.connectionDegree || lead.degree || '',
  mutualConnections: lead.sharedConnections || lead.mutualConnectionsCount || 0,
  followers: lead.followersCount || lead.followers || 0,
  headline: (lead.headline || lead.title || '').trim(),
  description: (lead.description || lead.summary || '').trim(),
  imageUrl: lead.imgUrl || lead.profileImageUrl || '',
  employeesEstimate: lead.companyEmployees || lead.employeesOnLinkedIn || '',
  industry: (lead.industry || lead.companyIndustry || '').trim(),
  _rawSource: 'phantombuster',
  _scrapedAt: new Date().toISOString()
})).filter(l => l.fullName || l.linkedinProfileUrl);

if (normalized.length === 0) {
  return [{ json: { error: 'No leads found in PhantomBuster output', rawKeys: Object.keys(raw) } }];
}

return normalized.map(l => ({ json: l }));

// Parse OpenAI response and calculate score
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  let enrichment = {};

  // Parse OpenAI response
  try {
    const choices = data.choices || (data.body && data.body.choices);
    if (choices && choices[0] && choices[0].message) {
      enrichment = JSON.parse(choices[0].message.content);
    }
  } catch (e) {
    enrichment = {
      industry_category: 'unknown',
      estimated_revenue: 'unknown',
      pain_points: [],
      tech_stack_signals: [],
      icp_match: 'OTHER',
      budget_signal: 'unknown',
      summary: 'Enrichment failed — manual review needed'
    };
  }

  // ══════════ SCORING MATRIX ══════════
  let score = 0;
  let scoreBreakdown = {};

  // 1. Industry Fit (0-25 pts)
  const ind = (enrichment.industry_category || '').toLowerCase();
  const indScores = { ecommerce: 25, distribution: 20, agency: 18, saas: 15, manufacturing: 12, services: 10 };
  scoreBreakdown.industry = indScores[ind] || 5;
  score += scoreBreakdown.industry;

  // 2. Company Size (0-20 pts)
  const emp = enrichment.estimated_employees || 0;
  if (emp >= 50 && emp <= 500) scoreBreakdown.size = 20;
  else if (emp >= 10 && emp < 50) scoreBreakdown.size = 12;
  else if (emp > 500) scoreBreakdown.size = 8;
  else if (emp >= 5 && emp < 10) scoreBreakdown.size = 6;
  else scoreBreakdown.size = 3;
  score += scoreBreakdown.size;

  // 3. Pain Signals (0-30 pts)
  const painCount = (enrichment.pain_points || []).length;
  scoreBreakdown.pain = Math.min(painCount * 8, 30);
  score += scoreBreakdown.pain;

  // 4. Budget Signal (0-15 pts)
  const revMap = { '>20M': 15, '20M+': 15, '5M-20M': 15, '1M-5M': 12, '<1M': 6, 'unknown': 4 };
  const rev = enrichment.estimated_revenue || 'unknown';
  scoreBreakdown.budget = revMap[rev] || 4;
  score += scoreBreakdown.budget;

  // 5. Accessibility (0-10 pts)
  let access = 0;
  if (data.linkedinProfileUrl || (data.fields && data.fields['LinkedIn URL'])) access += 5;
  const activity = (enrichment.linkedin_activity || '').toLowerCase();
  if (activity === 'high') access += 5;
  else if (activity === 'medium') access += 3;
  scoreBreakdown.accessibility = access;
  score += access;

  // Cap at 100
  score = Math.min(score, 100);

  // ══════════ TIER ASSIGNMENT ══════════
  let tier = 'C';
  if (score >= 80) tier = 'A';
  else if (score >= 70) tier = 'B';

  // ══════════ PRODUCT MATCHING ══════════
  const techStack = (enrichment.tech_stack_signals || []).map(s => s.toLowerCase());
  const painStr = (enrichment.pain_points || []).join(' ').toLowerCase();
  const icpMatch = (enrichment.icp_match || '').toUpperCase();

  let productPrimary = 'AI Growth Audit';
  let productSecondary = 'LeadScoring Pro';

  // Tech stack overrides
  if (techStack.some(t => ['shopify','tiendanube','vtex','magento','woocommerce'].includes(t))) {
    productPrimary = 'StoreSpy';
    productSecondary = 'PricingOptimizer';
  }
  // Industry-based matching
  else if (icpMatch === 'ECOMMERCE' || ind === 'ecommerce') {
    productPrimary = 'StoreSpy';
    productSecondary = 'AdIntel';
  }
  else if (icpMatch === 'DISTRIBUTION' || ind === 'distribution') {
    productPrimary = 'GeoGrowth';
    productSecondary = 'PricingOptimizer';
  }
  else if (icpMatch === 'AGENCY' || ind === 'agency') {
    productPrimary = 'Ghostwriter-Brand';
    productSecondary = 'PodScribe';
  }

  // Pain-based overrides
  if (painStr.includes('review') || painStr.includes('reseña') || painStr.includes('reputation')) {
    productPrimary = 'ReviewMining';
  }
  if (painStr.includes('ads') || painStr.includes('publicidad') || painStr.includes('advertising')) {
    productPrimary = 'AdIntel';
  }
  if (painStr.includes('churn') || painStr.includes('retención') || painStr.includes('retention')) {
    productPrimary = 'AI Growth Audit';
  }
  if (painStr.includes('seo') || painStr.includes('posicionamiento') || painStr.includes('search')) {
    productPrimary = 'SEO-Gap';
  }

  results.push({
    json: {
      airtableRecordId: data.airtableRecordId || data.id,
      score: score,
      tier: tier,
      scoreBreakdown: scoreBreakdown,
      productPrimary: productPrimary,
      productSecondary: productSecondary,
      icpMatch: enrichment.icp_match || 'OTHER',
      painPoints: (enrichment.pain_points || []).join('; '),
      techStack: (enrichment.tech_stack_signals || []).join(', '),
      estimatedRevenue: enrichment.estimated_revenue || 'unknown',
      summary: enrichment.summary || '',
      industryCategory: enrichment.industry_category || 'unknown',
      budgetSignal: enrichment.budget_signal || 'unknown',
      status: score >= 70 ? 'QUEUE_OUTREACH' : 'COLD',
      enrichedAt: new Date().toISOString()
    }
  });
}

return results;
